INSERT INTO reading_question_content_repair (reading_text_id, id, option_a, option_b, option_c, option_d, correct_answer, explanation) VALUES
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '07df2d88-cd17-4aea-b51c-40e25c360a8e'::uuid, 'Doğanın karmaşık sorunları çözemediği ve yetersiz kaldığı.', 'Milyonlarca yıllık evrimin verimli ve optimize çözümler üretmesi.', 'Mühendislerin doğayı yok ederek yeni tasarımlar geliştirmesi.', 'Teknolojinin tüm sorunları tek başına çözecek kadar gereksiz olması.', 'B', 'İfade, doğadaki canlıların uzun evrim sürecinde etkili ve verimli çözümler geliştirdiğini vurgular.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '2bc021dd-c68e-4aae-bc43-c86c0b49de7c'::uuid, 'Yalnızca tekstil ürünleri ve gündelik kıyafetlerin tasarımında.', 'Yalnızca gıda üretimi ve paketleme sektörlerinde kullanıldığı için.', 'Yalnızca eğlence teknolojileri ve oyun tasarımlarında kullanıldığı için.', 'Cerrahi dikişler, kurşun geçirmez giysiler ve uzay araçlarında.', 'D', 'Örümcek ağının dayanıklı ve esnek yapısı, cerrahi malzemelerden uzay araçlarına kadar farklı alanlara ilham verir.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '4c6f15f3-7b4b-465b-b373-83093ae80e39'::uuid, 'Eastgate Centre binası.', 'Termit Tower adlı bina.', 'Afrika Plaza adlı bina.', 'Green Building adlı bina.', 'A', 'Metin, Zimbabwe''deki Eastgate Centre''ın termit yuvasındaki pasif havalandırmadan ilham aldığını belirtir.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '50da2780-0e39-472c-b46d-b53d4a529eb1'::uuid, 'Çatıda güneş panelleri ve enerji depolama sistemleri kullandığı için.', 'Binayı dışarıdan tamamen kapatarak hava girişini engellediği için.', 'Doğal hava dolaşımı sağladığı için elektrikli iklimlendirme gerekmez.', 'Binada çok sayıda pencere ve parlak yüzey bulunduğu için.', 'C', 'Termit yuvası prensibi sıcak havayı yukarı taşır ve taze havayı içeri alır; böylece mekanik iklimlendirme ihtiyacı azalır.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '6aa116d3-53f0-493a-8609-e700128128d7'::uuid, 'Doğadaki benzer canlıları araştırıp çözümlerinden ilham almak.', 'Sorunu incelemeden doğrudan bir teknoloji mağazasına gitmek.', 'Aşırı ısınma veya enerji israfını önemsemeyip görmezden gelmek.', 'Problemi çözmek yerine yalnızca çevredeki insanlara şikâyet etmek.', 'A', 'Biyomimetik yaklaşım, önce aynı problemi doğada çözen canlıları incelemeyi önerir.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '7da6ee9d-6d6a-4bdc-a7f1-f486fea3bd94'::uuid, 'Doğal kaynakları sınırsızca kullanarak tasarımları hızlandırmak.', 'Sürdürülebilirlik için teknolojiden tamamen vazgeçmek.', 'Doğanın döngülerine saygılı tasarım ve tüketim tercihleri yapmak.', 'Çevredeki sorunları değiştiremeyeceğimizi düşünüp hiçbir şey yapmamak.', 'C', 'Doğayla iş birliği, doğal döngüleri gözeten ve kaynakları daha sorumlu kullanan seçimler yapmayı gerektirir.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, '87d7bfc3-edbb-4131-8648-49d74abf1fd5'::uuid, 'Bakterilerin tutunmasını azaltarak hastane enfeksiyonlarını düşürmesi.', 'Hastane duvarlarına daha parlak, estetik ve modern bir görünüm kazandırması.', 'Diğer yüzeylere göre daha ucuz ve kolay üretilmesi.', 'Her türlü kiri ve mikrobu hiçbir işlem yapılmadan temizlemesi.', 'A', 'Köpekbalığı derisindeki mikroskobik yapı bakteri tutunmasını zorlaştırır ve enfeksiyon riskini azaltmaya yardımcı olur.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, 'c37d2212-66ad-4121-9478-b2776f0117b2'::uuid, 'Yapraklarının güzel kokması ve uzun süre taze kalması.', 'Kendini temizleme ve suyu yüzeyden uzaklaştırma özelliği.', 'Diğer bitkilerden çok daha büyük ve geniş yapraklara sahip olması.', 'Yağmurdan sonra yüzeyinde parlak ve renkli desenler oluşması.', 'B', 'Lotus yaprağının mikroskobik yüzeyi su damlalarını yuvarlar; damlalar giderken kiri de taşır.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, 'd44eb237-4c95-4ef3-a3f1-03daf1d51f90'::uuid, 'Tekno ve loji; teknoloji biliminin temel kavramlarını anlatır.', 'Geo ve metrik; yeryüzünü ölçme ve haritalama anlamına gelir.', 'Bios yaşam, mimesis taklit; doğadan ilham alan tasarım.', 'Bio ve kimya; canlıların kimyasal yapılarını incelemeyi anlatır.', 'C', 'Biyomimetik, Yunanca bios (yaşam) ve mimesis (taklit) kelimelerinden türemiştir.'),
('0b323669-e098-4447-bae4-1ed7f3eb4641'::uuid, 'dbea0560-397e-4c40-a656-68061d13ee9b'::uuid, 'Örümcek ağındaki liflerin birbirine tutunma biçiminden.', 'Lotus yaprağının suyu ve kiri yüzeyden uzaklaştırmasından.', 'Köpekbalığı derisinin mikroskobik yüzey dokusundan.', 'Pıtrak dikenlerinin kumaşa tutunma biçiminden.', 'D', 'Velcro, pıtrak dikenlerinin kumaş liflerine tutunmasından esinlenilerek geliştirilmiştir.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '0408aeb6-3697-4f55-87e7-6ab70dae8ed2'::uuid, 'Kasaba halkı meydanda toplanıp bir kutlama hazırlamıştır.', 'Tekneleri bağlayıp pencereleri kalın tahtalarla kapatmışlardır.', 'Aileler eşyalarını toplayıp başka bir şehre gitmişlerdir.', 'Herkes denize inip fırtınanın büyüklüğünü yakından izlemeye başlamıştır.', 'B', 'Metinde balıkçıların teknelerini bağladığı ve dükkânların pencerelerinin tahtalarla kapatıldığı anlatılır.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '18c63661-3521-4b02-a214-5cb4f86a8ea7'::uuid, 'Karamel''in fırtınada çok uzun süre yüzdüğünü.', 'Karamel''in tekneyi kıyıya doğru çektiğini.', 'Karamel''in Hasan Amca''yı fark edip yardım çağırdığını.', 'Kaan''ın babasının sahil güvenliğini tek başına arayıp olayı çözdüğünü.', 'C', 'Hasan Amca, Karamel''in onu fark edip sesini duyurması sayesinde kurtulduğunu söyler.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '21c2c501-6e43-4918-b1e7-633444bc9fd0'::uuid, 'Sakin kalıp bir büyüğe haber vermeli veya yardım istemeliyim.', 'Korkumu saklayıp durumu kimseye söylememeliyim.', 'Tehlikeyi düşünmeden hemen dışarı doğru koşmalıyım.', 'Oyunuma devam edip sorunun kendiliğinden geçmesini beklemeliyim.', 'A', 'Hikâyede Kaan tek başına dışarı çıkmaz; babasından yardım ister.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '2c5e3eb8-a399-4cd0-ab67-c20022e028e1'::uuid, 'Karamel''in kısa süre içinde eve döneceğini düşündüğü için.', 'Şiddetli fırtınanın Kaan için tehlikeli olduğunu bildiği için.', 'Kaan''ın o akşam bitirmesi gereken ödevleri olduğu için.', 'Elindeki fenerin ışığının yeterince güçlü olmadığını düşündüğü için.', 'B', 'Babası, ağacı kökünden sökecek kadar şiddetli rüzgâr nedeniyle Kaan''ı dışarı bırakmaz.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '4a27056f-039a-42ed-b021-c556329d8c53'::uuid, 'Hayvanları eğlenmek için uzaktan korkutup kaçırmak.', 'Sıcak günlerde kapının önüne su ve mama bırakmak.', 'Yalnızca pahalı oyuncakları olan hayvanlarla ilgilenmek.', 'Sokakta karşılaşılan hayvanları hiç fark etmemek.', 'B', 'Su ve mama bırakmak, çevredeki hayvanların temel ihtiyacına yardımcı olabilecek güvenli bir davranıştır.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '6ba8e62a-3c5b-48b4-b12d-4ae2fd21eac6'::uuid, 'Hasan Amca''nın yerini bildirip yardım çağırmak.', 'Kaan''ın onunla sahilde oyun oynamasını istemek.', 'Gök gürültüsünden korktuğu için sessizce ağlamak.', 'Eve dönüp yemeğini beklediğini anlatmaya çalışmak.', 'A', 'Karamel, kayalıklardaki Hasan Amca fark edilsin diye sürekli havlar.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '82e691e4-0ed9-44b6-ab6f-ccad780025de'::uuid, 'Golden retriever cinsi Karamel adlı köpek.', 'Alman çoban köpeği Dost adlı, kasabada yaşayan bir köpek.', 'Husky cinsi Fırtına adlı bir köpek.', 'Dalmaçyalı Benekli adlı bir köpek.', 'A', 'Metnin başında Karamel''in altın sarısı tüylü bir golden retriever olduğu belirtilir.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '87af251f-1d85-4fd5-bd38-076a3bd83b30'::uuid, 'Evinin çatısı rüzgâr yüzünden uçup eşyaları bahçeye savrulmuştur.', 'Ormanda kaybolup yolunu uzun süre bulamamıştır.', 'Teknesi parçalanınca kayalıklarda mahsur kalmıştır.', 'Karamel''i ararken sahilde yönünü kaybetmiştir.', 'C', 'Hasan Amca''nın teknesi dalgalarda parçalanır ve kendisi kayalıklara tutunur.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, '91bdb44e-1049-4f2c-9c95-cf40fcd93751'::uuid, 'Fırtınalı günlerde denize hiç yaklaşmamak gerekir.', 'Köpekler insanların en yakın dostu ve en sevimli evcil hayvanlarıdır.', 'Kahraman olmak için mutlaka madalya almak gerekir.', 'Hayvanlar sadakatleri ve sezgileriyle kahramanlık gösterebilir.', 'D', 'Metin, Karamel''in sadakati ve dikkatiyle Hasan Amca''nın kurtulmasına odaklanır.'),
('f3dc2494-80bb-4d13-a5d0-5a7e2455d319'::uuid, 'a1c04b96-47ef-4286-be8b-e54b050573f3'::uuid, 'Kasaba ona ömür boyu ücretsiz mama vermiştir.', 'Belediye meydanın ortasına heykelini dikmiştir.', 'Herkes yalnızca başını okşayıp kahramanlığını kutlayarak teşekkür etmiştir.', 'Belediye başkanı tasmasına Cesaret Madalyası takmıştır.', 'D', 'Metinde belediye başkanının Karamel''in tasmasına özel Cesaret Madalyası taktığı anlatılır.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, '2511dd86-5660-491b-bf7c-8324e5a21c55'::uuid, 'Sosyal medya bağlantısını yavaşlatıp içeriklerin geç açılmasına neden olur.', 'Kullanıcıya yalnızca kendi görüşünü destekleyen içerikleri gösterir.', 'Kullanıcıya sürekli müzik dinletip haberleri geri planda bırakır.', 'Kullanıcının hesabını otomatik olarak kilitleyip erişimi sınırlar.', 'B', 'Yankı odası, algoritmanın benzer görüşleri tekrar tekrar göstererek kişiyi farklı fikirlere kapatmasıyla oluşur.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, '44a62a68-ffcc-47e4-8efb-c2de6993e0a2'::uuid, 'Her platformda aynı şifreyi kullanıp hatırlamayı kolaylaştırmalıdır.', 'Şifresini kimseyle paylaşmayıp başka güvenlik önlemi almamalıdır.', 'Güçlü ve karmaşık şifreler kullanıp mümkünse 2FA''yı açmalıdır.', 'Şifrelerini yalnızca harflerden oluşturarak kolayca yazmalıdır.', 'C', 'Karmaşık ve benzersiz şifreler ile iki faktörlü doğrulama, hesap güvenliğini güçlendirir.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, '47c6d995-4eec-467a-9a61-e96bdbfecaf9'::uuid, 'Dijital ayak izi ve itibar yönetimi.', 'Çevrimiçi oyun alışkanlığı ve oyun bağımlılığı.', 'İnternetten alışveriş yapma ve e-ticaret kullanımı.', 'Şifre, virüs ve hesap korumasına dayalı siber güvenlik.', 'A', 'Sosyal medya profilleri, kişinin çevrimiçi bıraktığı iz ve oluşan dijital itibarla doğrudan ilişkilidir.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, '507682eb-f98b-469f-81d3-1c74ceb44fb3'::uuid, 'İnternet kotasını gereksiz yere tüketip bağlantıyı yavaşlattığı için.', 'Haberin çoğu kişi tarafından okunmamasına neden olduğu için.', 'Telefonun şarjını bitirip cihazın daha erken kapanmasına yol açtığı için.', 'Yanlış bilgiyi yayarak toplumsal bilgi kirliliğine ortak olduğu için.', 'D', 'Doğrulanmamış haberleri paylaşmak yanlış bilginin yayılmasına ve toplumun yanıltılmasına katkıda bulunur.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, '8a61d317-bdc7-4002-8770-c614d5f534db'::uuid, 'Dijital imza ve elektronik belge doğrulaması.', 'Spam ve istenmeyen mesajların çevrimiçi kaydı.', 'Dijital ayak izi ve çevrimiçi etkinliklerin kalıcı izi.', 'IP adresi ve internete bağlanan cihazın teknik numarası.', 'C', 'Paylaşımlar, aramalar ve diğer çevrimiçi davranışlar birlikte dijital ayak izini oluşturur.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, 'c7fe49bc-f461-471b-8936-14d47a8db82d'::uuid, 'Teknolojiden bilinçli olarak bir süre uzaklaşıp zihinsel dengeyi korumak.', 'Yeni bir sosyal medya hesabı açıp çevrimiçi etkinliği artırarak zaman geçirmek.', 'Çevrimiçi oyun oynama süresini artırıp daha çok görev tamamlamaya çalışmak.', 'Bilgisayara virüs programı kurup bütün zararlı yazılımları otomatik silmek.', 'A', 'Dijital detoks, teknoloji kullanımına bilinçli bir ara vererek zihinsel dengeyi ve dikkati toparlamaktır.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, 'dc3f37f1-56d9-4c4d-82ef-13af61dd30f8'::uuid, 'Daha pahalı olması ve herkes için maddi yük oluşturması.', 'Sadece çocuklarda görülmesi ve yetişkinleri etkilememesi.', 'Yalnızca geceleri yaşanması ve gündüz tamamen sona ermesi düşüncesi.', 'Evin içine kadar ulaşabilmesi ve yirmi dört saat sürebilmesi.', 'D', 'Siber zorbalık, internet bağlantısı üzerinden kişinin evine ve özel alanına günün her saatinde ulaşabilir.'),
('1ddf173f-6f95-4eb1-ac94-5e64f0bae60f'::uuid, 'f82f27a1-833b-4526-b8e1-af28528fc1ec'::uuid, 'İnternette konuşan kişileri sessizleştirip iletişimi tamamen azaltması.', 'Sahte cesaret verip yüz yüze söylenemeyen hakaretleri kolaylaştırması.', 'Çevrimiçi ortamlarda yardımlaşmayı ve dayanışmayı sürekli artırması.', 'İnsanları gerçek hayatta daha cömert ve daha anlayışlı yapması.', 'B', 'Anonimlik, kişinin karşısındakinin yüzünü görmeden normalde söylemeyeceği hakaretleri yazmasını kolaylaştırabilir.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '486ef26e-c4aa-4d68-bc7f-b660c2118d5f'::uuid, 'Yalnızca orkestralarda çalınan geleneksel müziğin önemini vurguladığını.', 'Herkesin özgün bir ses katarak dünyadaki çeşitliliği artırabileceğini.', 'Müzik üretiminde para ve şöhretin en önemli ölçüt olduğunu savunduğunu.', 'Yeni bir enstrüman satın almanın müzikte başarı getireceğini anlattığını.', 'B', 'Ozan''ın sözü, herkesin kendi özgün katkısıyla müziğin ve dünyanın çeşitlenebileceğini anlatır.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '490e9f4e-a179-4ec4-aaa5-838274e0d474'::uuid, 'Biyoloji bilgisinin geleneksel sanatlardan daha değerli olduğunu savunması.', 'Sanatın biçiminin duygudan her zaman önce geldiğini söylemesi.', 'Sanatın türünden çok, insanda oluşturduğu duygu ve etkinin önemli olduğunu.', 'Konserin başarısız geçtiğini ve izleyicilerin memnun kalmadığını açıklaması.', 'C', 'Öğretmen, gitar ya da elektronik müzik ayrımından çok sanatın insanlarda oluşturduğu etkiye odaklanır.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '52580f35-01bf-4beb-81fa-d15787f728cf'::uuid, 'Bilgisayar, mikser ve sentezleyici gibi elektronik ekipmanları.', 'Keman, akordeon ve diğer geleneksel yaylı çalgıları çalmaya yarayan araçları.', 'Davul, bas gitar ve sahnede kullanılan ritim araçlarını birlikte.', 'Yalnızca piyano tuşlarını ve klasik nota kitaplarını incelemeyi.', 'A', 'Ozan, diğer arkadaşlarından farklı olarak bilgisayar, mikser ve sentezleyiciye ilgi duyar.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '645c1771-07da-4220-8a75-64ea0443967c'::uuid, 'Müziği tamamen bırakıp ailesinin istediği güvenli işe yönelerek hayatını değiştirdi.', 'Üniversitede ses mühendisliği okuyup geceleri prodüksiyonuna devam ederek.', 'Yalnızca aile işinde çalışıp müzikle ilgilenmeyi uzun süre erteleyerek karar verdi.', 'Eğitimini bırakıp tek başına yurt dışına gitmeye karar vererek ilerledi.', 'B', 'Ozan, ailesinin güvenlik kaygılarını üniversite eğitimiyle karşılar; tutkusu olan prodüksiyonu da sürdürür.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '6ac79140-fb0f-4cd8-8368-0972eb38530a'::uuid, 'Yalnızca ailesinin istediği güvenli işi seçmesini ve hobisini bırakmasını gerektirir.', 'Aile desteğini önemsemeyip bütün kararları tek başına vermesini ve uzaklaşmasını sağlar.', 'İki tarafın kaygılarını karşılayarak güvenlik ve tutkuyu dengelemesini sağlar.', 'Anlaşmazlığı çözmeden tartışmanın daha uzun sürmesine ve ilişkilerin gerilmesine neden olur.', 'C', 'Uzlaşma, Ozan''ın eğitim ve güvenlik planını korurken elektronik müziğe de zaman ayırmasını sağlar.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '6c165212-3756-4436-964b-132ba9cdfb8f'::uuid, 'Elektronik müziğin zararlı ve dinlenmemesi gereken bir tür olduğunu kanıtladığını.', 'Öğrencilerin konserden sıkılıp salondan ayrılmak istediğini ve dans etmediğini.', 'Konser sırasında hoparlör sisteminin bozulup sesin uzun süre kesildiğini.', 'Özgün bir performansın önyargıları kırarak insanları etkileyebileceğini.', 'D', 'Başta şüphe duyan öğrencilerin dans etmeye başlaması, performansın önyargıyı değiştirdiğini gösterir.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, '97fd1e1a-d1ff-4341-8072-d52adf40408c'::uuid, 'Geleneksel olmayan dijital sanatların yeterince tanınmaması veya küçümsenmesi.', 'Geleneksel ve dijital bütün sanat biçimlerine toplumda her zaman eşit değer verilmesi.', 'Toplumun müziği genel olarak sevmediği ve dinlemek istemediği düşüncesi.', 'Elektronik müzik ekipmanlarının her öğrenci için çok pahalı olduğu düşüncesi.', 'A', 'Ailenin sorusu, gelenek dışı dijital sanatların toplumda hâlâ küçümsenebildiği algısını yansıtır.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, 'd438643b-86dc-4453-823c-0006bcf71f31'::uuid, 'İçindeki sesi dinleyip emek vererek kendine özgü bir yol kurabileceğini.', 'Çevresindeki insanlar beğenmediğinde hobiyi hemen bırakması gerektiğini.', 'Kendi ilgileri yerine yalnızca başkalarının tavsiyelerine göre hareket etmesi gerektiğini.', 'Farklı bir hobi seçmenin hiçbir anlamı olmadığını ve denememesi gerektiğini.', 'A', 'Ozan''ın hikâyesi, kişinin farklı görülen ilgisini emekle geliştirerek özgün bir yol kurabileceğini gösterir.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, 'ec3572ef-d897-4e93-866a-b48d9547d85c'::uuid, 'Konservatuvarda yıllar süren resmi bir eğitim alarak.', 'Ailesinden gizlice aldığı haber ve tavsiyelerle öğrenerek.', 'YouTube eğitimlerini izleyip kendi kendine deneyerek öğrenmiştir.', 'Özel bir prodüktörün ücretli derslerine düzenli katılarak öğrenmiştir.', 'C', 'Ozan, beat, ses mühendisliği ve miksajı YouTube eğitimleriyle kendi kendine deneyerek öğrenir.'),
('256d1966-24e7-4a96-aeb2-7b9f7f6e47e3'::uuid, 'fb8a1611-a8ee-446b-bf13-970477ff6d5f'::uuid, 'Ailesinin sonunda müzik kariyerini onaylaması ve destek vermesi.', 'Okul konserinin beklenmedik bir nedenle iptal edilmesi.', 'Üniversite sınavını kazanıp ses mühendisliğine başlaması.', 'Yabancı prodüktörün SoundCloud''da bıraktığı olumlu yorum.', 'D', 'Yabancı prodüktörün “Farklı bir sesin var, devam et” yorumu Ozan''ın emeğinin ilk kez dışarıdan fark edildiği dönüm noktasıdır.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '03d547a4-3cf0-4bae-bc1f-79ca9f9a9f2e'::uuid, 'Yıldırım jeneratör dairesine düşüp sistemleri bozmuştur.', 'Fenerin yakıtı gece yarısı tamamen tükenmiştir.', 'Rüzgâr camları kırıp lambayı doğrudan söndürmüştür.', 'Kerem Dede elektrik şalterini yanlışlıkla kapatıp feneri söndürmüştür.', 'A', 'Metinde yıldırımın jeneratör dairesine isabet ettiği belirtilir.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '0ee434a5-d5c3-4a2a-bda4-3526b572d5a1'::uuid, 'Dolunay nedeniyle fener ışığı denizden yeterince görünmeyeceği için.', 'Fırtına görüşü azaltıp gemiler için kaza riski oluşturduğu için.', 'Önemli bir yetkili o gece adayı ziyaret edeceği için.', 'Fenerin düzenli bakım zamanı o gece geldiği için.', 'B', 'Kerem Dede, denizcilerin fırtınada rotalarını fener ışığıyla bulacağını söyler.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '1460ef68-0392-4a59-aca0-124ee5e0b86f'::uuid, 'Yakılan ateşin gemiye yol gösterip onu kurtardığını.', 'Kaptanın fener bekçisine resmî olarak ceza vermek istediğini.', 'Geminin ağır hasar alıp hareket edemediğini.', 'Geminin adada yakıt ikmali yapmak istediğini.', 'A', 'Kaptan, ateş olmasaydı geminin sulara gömüleceğini ifade eder.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '4952da1a-94d6-43c7-b03f-ddf4c11e9240'::uuid, 'Depoda bulunan güçlü el fenerlerini.', 'Gemilerden gönderilen parlak işaret fişeklerini.', 'Odun ve kuru otlarla yaktıkları büyük ateşi.', 'Kulede saklanan gaz lambalarını.', 'C', 'Ali kuru ot ve odun taşır, Kerem Dede de balkonda ateş yakar.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '5d8d4157-e70b-46de-9900-24adf5ce0ac3'::uuid, 'Ali''yi sakinleştirip çözüm düşünmeye yönlendirmiştir.', 'Kendisi de paniğe kapılıp ne yapacağını bilememiştir.', 'Ali''ye kızıp onu hemen odasına göndermiştir.', 'Yardım aramak için kasabaya tek başına koşmuştur.', 'A', 'Kerem Dede Ali''ye korkmamasını söyler ve eski yöntemi hatırlatır.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '644f560d-d8d5-4307-8478-112a7ae03c52'::uuid, 'Kırk yıldır fenerin bekçiliğini yapmaktadır.', 'Otuz yıldır fenerin bekçiliğini yapmaktadır.', 'Yirmi yıldır fenerin bekçiliğini yapmaktadır.', 'On yıldır fenerin bekçiliğini yapmaktadır.', 'B', 'Metnin ilk bölümünde Kerem Dede''nin otuz yıllık bekçi olduğu yazılıdır.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '6dea2c89-a2b4-47e1-961f-2fafb37b4ae0'::uuid, 'Ali''nin dökme demir merdivenleri dikkatle ve zorlanarak tırmanmasıyla.', 'Telsizden fırtına uyarısının gelmesi ve geminin alarma geçirilmesiyle.', 'Elektrik kesilince eski usul ateş yakılıp geminin kurtarılmasıyla.', 'Gemi kaptanının sabah kuleye teşekkür için özel olarak gelmesiyle.', 'C', 'Eski zamanlarda kullanılan ateş yakma yöntemi, teknoloji devre dışıyken çözüm olur.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, '70a26c1a-6800-4923-8ff2-b6fd674985ce'::uuid, 'Kulenin en tepesindeki camlı bölümde ve ışığa yakın yerde.', 'Kulenin giriş kapısının hemen önünde ve koridor tarafında.', 'Balkonda rüzgârdan korunan bir noktada.', 'Kayalıkların denize en yakın kısmında, kıyıya bakan yerde.', 'C', 'Metin ateşin kulenin balkonunda, rüzgârdan korunaklı bir noktada yakıldığını belirtir.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, 'bca5980f-b24c-4f1d-ba2b-c079ecb3a72a'::uuid, 'Teknolojik araçlara her durumda güvenmek gerektiğini.', 'İnsan aklı ve yaratıcılığının zorlukları aşabileceğini.', 'Eski yöntemlerin her zaman yeni yöntemlerden iyi olduğunu.', 'Deniz fenerlerinin artık hiçbir işe yaramadığını.', 'B', 'Kerem Dede, teknoloji çalışmasa da aklın çözüm bulabileceğini vurgular.'),
('91cbc4da-a87f-41cd-85ad-d454148b9fd5'::uuid, 'e9972c74-5118-4b29-a94b-2796d4dad8cf'::uuid, 'Fırtınanın tahmin edilenden daha kısa sürede sona ereceğini.', 'Başka bir geminin yaklaşıp onları zamanında kurtaracağını.', 'Jeneratörün kendiliğinden yeniden çalışıp elektriği getireceğini.', 'Çözüm üretemeyip geminin kayalıklara çarpabileceğini.', 'D', 'Panik yerine sakin düşünmeleri, ateşi yakıp gemiye güvenli yol göstermelerini sağlar.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '23d0135f-3045-4f01-8b3a-e965743ac192'::uuid, 'Kalemin sihrinin yalnızca dolunay gecelerinde ve belirli günlerde ortaya çıktığı.', 'Kalem korkuları azaltıp içindeki yeteneği görünür kılmasına yardım ediyordu.', 'Kalemin dünyanın en değerli ve eşsiz sanat eseri olarak kabul edildiği.', 'Kalemi kullanmak için yıllarca resim eğitimi ve özel yetenek gerektiği.', 'B', 'Yaşlı adam, kalemin korkuları silip Mert''in içindeki yeteneği ortaya çıkardığını söyler.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '42d4acb6-b933-4198-b378-1d03e9e0f5e3'::uuid, 'Öğretmeninin her derste çok zor ödevler verdiğini düşünüyordu.', 'Kullandığı resim malzemelerinin yeterince kaliteli olmadığını sanıyordu.', 'Kendisini yeteneksiz görüyor ve çizimlerini başarısız buluyordu.', 'Resim dersi yerine arkadaşlarıyla oyun oynamak istiyordu.', 'C', 'Mert başlangıçta çizdiklerinin berbat olduğuna inanıp yeteneğin seçilmiş kişilerde bulunduğunu düşünür.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '44e445ae-980f-4015-95a0-cafea0d29e09'::uuid, 'Resim yapmayı bırakıp bütün zamanını spora ve başka uğraşlara ayırırdı.', 'Kısa sürede ünlü bir ressam olup dünyayı dolaşmaya çalışırdı.', 'Kalemi kullanmayı sürdürür, kendi emeğine güvenmeyi öğrenemezdi.', 'Kalemi arkadaşlarına satarak para ve kazanç sağlamaya çalışırdı.', 'C', 'Yaşlı adamın sözleri Mert''in başarının kalemde değil kendi çabasında olduğunu fark etmesini sağlar.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '4dd19177-cc55-4e90-b3e2-758309f36eb4'::uuid, 'Kalemin ucunu daha dikkatli ve düzgün açmıştı.', 'Kendi becerisine güvenmeye ve denemeye başlamıştı.', 'Resim kâğıdı diğer kullandıklarından daha kaliteli çıkmıştı.', 'Bir arkadaşı ona fark ettirmeden çiziminde yardım etmişti.', 'B', 'Mert sıradan kalemle çizerken artık kendisini yeteneksiz görmediği için resmi gelişir.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '5927c23c-7d16-4acf-8cfb-1c814795ac4f'::uuid, 'Eski eşyaların her zaman olağanüstü güçleri ve gizli etkileri olabilir.', 'Yetenek doğuştan gelir ve çalışmayla hiçbir zaman değiştirilemez.', 'Başarı için mucize beklemek yerine emek vermek ve inanmak gerekir.', 'İyi resim yapmak için pahalı boya, fırça ve kalemler mutlaka şarttır.', 'C', 'Hikâyenin ana dersi Mert''in pratik yaparak kendine güven kazanmasıdır.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '71856379-3bd0-411a-8dd9-664a1f103368'::uuid, 'Aylar boyunca düzenli çalışıp pes etmemesi.', 'Sihirli kalemi kaybedince başka seçeneği kalmaması.', 'Öğretmeninin ona özel resim dersleri vermesi.', 'Rüyadaki yaşlı adamın ona yeni bir kalem getirmesi.', 'A', 'Mert aylarca pratik yaptıkça her resminin önceki çalışmasından daha iyi olduğunu görür.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, '9c56779a-3dd2-40a1-9d13-7224edc6aaed'::uuid, 'Altın renkli, işlemeleri ve ince desenleri bulunan eski bir kalemdi.', 'Bordo renkli, yıldız desenli parlak bir tükenmez kalemdi; kutusu da yeniydi.', 'Silgili, sade ve sarı renkli ahşap bir kurşun kalemdi; sıradan görünüyordu.', 'Hayvan figürleri bulunan mavi renkli plastik bir kalemdi; yeni görünüyordu.', 'A', 'Mert yapraklar arasında altın renkli, işlemeli ve desenli eski bir kurşun kalem bulur.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, 'b30b8a36-b262-422e-ab5c-957f09c29ab1'::uuid, 'Resimde kullandığı renklerin birbiriyle uyumsuz olduğunu düşündüğü için.', 'Öğretmeninin resmi beğenmeyeceğinden endişe ettiği için.', 'Ortaya çıkan başarının kendi emeğine ait olmadığını hissettiği için.', 'Arkadaşlarının resmi kıskanıp onunla konuşmayacağından korktuğu için.', 'C', 'Mert resmin güzel olmasını kendi yeteneğinden değil, kalemin sihrinden kaynaklanmış sanır.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, 'b3abf744-f4a7-47e7-8f04-c181bf7efcbf'::uuid, 'Dalgaların yükseldiği fırtınalı bir deniz manzarası çizmiştir.', 'Bacası tüten ve perdeleri görünen kusursuz bir ev çizmiştir.', 'Gökyüzünde uçurtmalarla kuşların bulunduğu bir manzara çizmiştir.', 'Geniş gövdeli ve yaprakları yoğun bir çınar ağacı çizmiştir.', 'B', 'Kalemi denediğinde Mert önce bacası ve perdeleri görünen bir ev çizer.'),
('3cc50491-5bc1-434e-99ea-a0882c293b1b'::uuid, 'd413b8f2-fbba-4348-a9ef-07512a6635b0'::uuid, 'Kalemi kadife bir kutuya koyup ileride kullanmak üzere saklamaya.', 'Kalemi en yakın arkadaşına vererek onun da resim yapmasını sağlamaya.', 'Kalemi bulduğu yere geri bırakıp olaydan hiç söz etmemeye.', 'Kalemi öğretmenine teslim ederek sınıfta sergilenmesini istemeye.', 'A', 'Mert kalemi kadife kutuya koyar; kendine güvenmeyen başka bir çocuğa yardımcı olabileceğini düşünür.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '007e00a4-12fc-45c5-a7f4-a77f1681c5ba'::uuid, 'Para, statü ve onay olmasaydı ne yapmak isterdin?', 'Hangi üniversiteyi seçmek istediğini şimdiden biliyor musun?', 'En sevdiğin dersi ve bu dersteki hedefini biliyor musun?', 'Ailende kaç kişi olduğunu ve kardeş sayını biliyor musun?', 'A', 'Sitenin ilk sorusu, para ve başkalarının onayından bağımsız olarak kişinin gerçekten ne yapmak istediğini sorgular.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '3f5dfc5d-17b1-43ec-8881-5d6959225059'::uuid, 'Mühendislik alanında eğitim almayı ve bu alanda çalışmayı istemek.', 'Doktorluk mesleğini seçip hastalara yardım etmeyi istemek.', 'Yazı yazmayı ve yazarlıkla ilgili üretimler yapmayı.', 'Avukatlık okuyup hukuk alanında uzun vadeli bir kariyer kurmak.', 'C', 'Selin, para ve statü önemsiz olsaydı ilk olarak yazı yazmak istediğini fark eder.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '78c3601e-9cc0-4d1a-9aa3-0283d6dfcf81'::uuid, 'Varsayımları araştırıp ilgili kişilerle açıkça konuşarak test etmek.', 'Kararı hiç düşünmeden hızlıca verip sonuçlarını beklemek ve değerlendirmek.', 'Kendi kararını bırakıp yalnızca çevresindeki kişilerin görüşlerini dinlemek.', 'Herhangi bir adım atmadan kararı süresiz biçimde ertelemek ve beklemek.', 'A', 'Zihinsel engelleri sınamak için varsayımları araştırmak ve ilgili kişilerle doğrudan konuşmak gerekir.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '79591f60-a7b5-4bce-ad65-dce704977f0b'::uuid, 'Hiçbir bölümü sevmediğini ve seçim yapamayacağını düşünüyordu.', 'Çevresinden gelen farklı öneriler kendi isteğini duymasını zorlaştırıyordu.', 'Sınavdan düşük puan aldığı için seçeneklerinin tamamen kapandığını sanıyordu.', 'Ailesinin maddi durumu kötü olduğu için karar veremediğini düşünüyordu.', 'B', 'Selin, ailesi, arkadaşları ve öğretmenlerinden gelen farklı yönlendirmeler arasında kendi sesini duyamıyordu.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '7b1e046a-85f7-48a1-8d8a-59eef7bdff10'::uuid, 'Yalnızca tutkuyu izleyip ekonomik koşulları ve riskleri hesaba katmamayı.', 'Tamamen güvenli yolu seçip kişisel ilgilerini uzun süre ertelemeyi.', 'Tutkuyu ekonomik güvenlikle dengeleyen çok yönlü kariyer planını.', 'Kariyer için hiçbir hedef belirlemeden gelişigüzel ve plansız ilerlemeyi.', 'C', 'Selin''in hibrit planı, yazarlık tutkusunu iletişim ve içerik üretimiyle ekonomik bir zemine bağlar.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, '836e83f8-f82f-4329-ad39-93c738373b37'::uuid, 'Yalnızca yazarlık yapacağını ve başka bir alan düşünmediğini ailesine söylemeyi.', 'Ailesine herhangi bir plan sunmadan kararını açıklamayı ve destek beklemeyi.', 'Üniversite yerine doğrudan başka bir ülkeye gideceğini ailesine bildirmeyi.', 'İletişim okuyup içerik üreticisi olmak ve yazarlığı sürdürmek.', 'D', 'Selin, İletişim Fakültesi''ni okuyup içerik üretirken yazarlığı paralel sürdüreceğini anlatır.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, 'b3cf1c62-f9ee-435b-978e-3337c5b38207'::uuid, 'Engellerin çoğunun zihnindeki varsayımlar olduğunu ve test edilmediğini fark etti.', 'Soruların hiçbir şeyi değiştirmediğini ve kararının aynı kaldığını düşünerek ilerledi.', 'Korkularının arttığını ve yeni bir karar vermenin daha zorlaştığını hissetti.', 'Kariyer hedefinden bütünüyle vazgeçmesi gerektiğine inanmaya başladı.', 'A', 'Selin, bazı engellerin dış koşul değil, gerçekliğini hiç sınamadığı varsayımlar olduğunu anlar.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, 'c288a606-6a03-4493-96bb-571698ba300a'::uuid, 'Ailesinin onu sevmediğini ve artık desteklemeyeceğini gösteren bir işarettir.', 'Olumsuz tepki varsayımının gerçek olmadığını ve açık iletişimin işe yaradığını gösterir.', 'Ailesinin konuya hiç önem vermediğini ve bu nedenle ilgilenmediğini gösterir.', 'Ailesinin kararına kızdığını fakat bunu uzun süre sakladığını ve açıklamadığını gösterir.', 'B', 'Ailesinin beklediği kadar olumsuz tepki vermemesi, açık konuşmanın yanlış varsayımları değiştirebileceğini gösterir.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, 'd96cd7bb-77a9-4039-b525-84fe0a2294b2'::uuid, 'En çok parayı hangi mesleğin ve sektörün kazandırdığını sormak.', 'Çevresindeki herkesin hangi mesleği ve bölümü seçtiğini sormak.', 'Dış baskı olmasa gerçekten ne yapmaktan mutluluk duyardım?', 'En kolay ve en az sorumluluk gerektiren seçeneğin hangisi olduğunu sormak.', 'C', 'Hikâye, kişinin dış beklentilerden bağımsız olarak kendi ilgisini ve mutluluğunu sorgulamasını önerir.'),
('132765ef-9444-4868-8bab-3167d6d2c879'::uuid, 'f935f6a3-f2cb-4e6c-b036-b8f02d0041f3'::uuid, 'Bilgisayarda yeni bir şifre oluşturup bunu gizli tutması.', 'Geleceği için başkalarının okuyamayacağı gizli bir kod yazması.', 'Sitenin sözlerini dikkate almadan karar vermekten vazgeçmesi.', 'Kendi değerleriyle uyumlu bir gelecek tasarlaması.', 'D', '“Geleceğini şifrelemek”, Selin''in başkalarının beklentileri yerine kendi değerleriyle yönünü belirlemesini simgeler.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '12e520f7-7ec1-41b1-a0bf-8637c54d2d68'::uuid, 'Doğrusal olmayan konvektif terim denklemleri karmaşıklaştırır.', 'Denklemlerin çok kısa olması çözüm adımlarını belirsizleştirir.', 'Yalnızca iki boyutlu problemlere uygulanabildikleri için sınırlıdır.', 'Viskozite terimini içermedikleri için fiziksel etkiler eksik kalır.', 'A', 'Navier–Stokes denklemlerindeki doğrusal olmayan konvektif terim, çoğu durumda analitik çözümü zorlaştırır.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '35d47439-9739-425c-8eb6-96230ad00dc1'::uuid, 'Yalnızca büyük girdapları çözer ve küçük ölçekleri dışarıda bırakır.', 'Türbülansı tamamen ihmal eder ve yalnızca ortalama akışı hesaplar.', 'Sadece laminer akışlar için geçerlidir ve türbülans üretemez.', 'Tüm ölçekleri doğrudan çözer; hesaplama maliyeti yüksektir.', 'D', 'DNS, türbülansın tüm uzay ve zaman ölçeklerini modelleme yaklaşımı kullanmadan çözer; bunun bedeli yüksek hesaplama maliyetidir.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '48a19351-b080-413e-b471-fd3b8183b233'::uuid, 'Yalnızca görsel sunum için yapılır; sayısal sonuçları değiştirmeyen bir kontroldür.', 'Sadece akademik bir gerekliliktir; endüstrideki tasarım kararlarında kullanılmaz.', 'CFD çalışmalarında bu iki kavramın kullanılmasına gerek olmadığı düşünülür.', 'Sayısal hatayı ve fiziksel doğruluğu kontrol ederek güvenilir sonuç sağlar.', 'D', 'Doğrulama sayısal hataları, geçerleme ise sonuçların fiziksel deneylerle uyumunu sınar; ikisi birlikte güvenilirlik sağlar.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '83db6201-7b9e-475c-967a-9cabfaf82fa9'::uuid, 'Akışkan içindeki basınç düşüşünü tek başına ölçen boyutsuz sayıdır.', 'Re = ρVL/μ ile tanımlanır ve laminer-türbülanslı geçişi belirler.', 'Akışkanın yalnızca sıcaklık değişimini gösteren boyutsuz ölçüdür.', 'Sadece gazlarda kullanılabilen ve sıvılara uygulanamayan sayıdır.', 'B', 'Reynolds sayısı yoğunluk, hız, karakteristik uzunluk ve viskoziteyle tanımlanır; akış rejimini değerlendirmeye yardım eder.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '878e7f7f-3c83-4d0c-b5d1-c5493e4a2652'::uuid, 'Akışkanın katıdan daha yoğun ve ağır olması gerektiği düşüncesidir.', 'Akışkanın ısıyı katılardan farklı biçimde iletmesi ve daha kolay yaymasıdır.', 'Akışkanın kayma gerilmesi altında sürekli biçimde deforme olmasıdır.', 'Akışkanın uygulanan kuvvete rağmen şeklini uzun süre korumasıdır.', 'C', 'Akışkan, kayma gerilmesi uygulandığı sürece sürekli deforme olarak akmaya devam eder; bu özellik onu katıdan ayırır.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, '9c147384-906e-4583-bc4c-bc81a1979ad5'::uuid, 'Üç yöntemin de her problemde aynı doğruluğu ve hesaplama maliyetini sunmasıdır.', 'RANS tüm türbülansı modeller; LES büyük yapıları çözer; DNS tüm ölçekleri hesaplar.', 'Yalnızca DNS''in pratik mühendislik problemlerinde kullanılabilmesi ve diğerlerinin kullanılamamasıdır.', 'RANS''ın en doğru ve aynı zamanda en pahalı yöntem olması; diğerlerini geride bırakmasıdır.', 'B', 'RANS hız ve düşük maliyet, LES orta düzey ayrıntı, DNS ise en yüksek ayrıntı ve maliyet dengesini temsil eder.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, 'c77195bb-d501-432f-b22d-e70f100f5b0d'::uuid, 'Kaldırma kuvvetinin artmasına ve kanadın daha verimli çalışmasına yol açar.', 'Akışın daha laminer hâle gelmesini ve sürtünmenin azalmasını sağlar.', 'Sürüklemeyi artırır, verimi düşürür ve kanatta stall riskini yükseltir.', 'Akışkanın viskozitesini azaltır ve sınır tabakayı daha kararlı yapar.', 'C', 'Sınır tabakası ayrıldığında akış yüzeyden kopar; sürükleme artar, verim düşer ve kanat taşıma kaybına uğrayabilir.'),
('1057a06c-299f-48e8-bbad-3ff02e2153d7'::uuid, 'fd08655b-c5f3-4500-a106-aed270dcfb9b'::uuid, 'Basınç, kinetik ve potansiyel enerji toplamını korur.', 'Akışkanın toplam kütlesini ve her noktadaki yoğunluğunu korur.', 'Akışkanın hareket miktarını ve momentum değişimini korur.', 'Akışkanın viskozitesini ve sıcaklıkla değişimini korur.', 'A', 'Bernoulli denklemi uygun koşullarda akım çizgisi boyunca basınç, kinetik ve potansiyel enerji toplamını korur.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '1851f307-1c70-40c2-be57-520dae9f370e'::uuid, 'Yüzlerce riskli girişime yatırım yapıp bir büyük başarının kayıpları karşılamasını hedeflemek.', 'Yalnızca risksiz banka faizine ve devlet güvenceli araçlara yatırım yaparak sermayeyi korumak.', 'Her girişimden küçük fakat kesin ve garanti bir kâr bekleyerek riski sınırlamak.', 'Yalnızca inşaat sektöründeki şirketlere yatırım yapmayı ve diğerlerini dışarıda bırakmak.', 'A', 'Girişim sermayesi yüksek riskli birçok şirkete yatırım yapar; birkaç büyük başarı toplam portföyün getirisini belirler.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '57768656-893e-43a7-82e2-63daa2a78522'::uuid, 'Unicorn adlı yüksek değerli girişim.', 'Ejderha adlı yüksek değerli bir girişim.', 'Dev adlı yüksek değerli bir girişim.', 'Pegasus adlı yüksek değerli bir girişim.', 'A', 'Değeri bir milyar doları aşan yüksek potansiyelli start-up''lara Unicorn adı verilir.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '5a1e7dfb-ff17-4143-a3f1-0af50f836eca'::uuid, 'Platformun çok fazla reklam göstererek gelirini artırması.', 'Ürünün ücretsiz olması sayesinde herkesin aynı anda kullanmaya başlaması.', 'Kullanıcı sayısı arttıkça ürünün kişi başına değerinin artması.', 'İnternet bağlantısının rakip platformlardan daha hızlı olması.', 'C', 'Ağ etkisinde her yeni kullanıcı, platformu diğer kullanıcılar için daha değerli ve vazgeçilmez hâle getirir.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '7d23b26d-e202-4c9f-8126-05427aa45610'::uuid, 'Airbnb''nin kış aylarında kurulmasının özel bir avantaj sağlaması.', 'Kurucuların kullandığı saatin çok doğru çalışmasının başarı getirmesi ve belirleyici olması.', 'Zamanlamanın önemsiz olması ve iyi fikrin her dönemde kabul edilmesi.', '2008 krizinde ek gelir ihtiyacının ev kiralama fikrini kabul ettirmesi.', 'D', 'Ekonomik kriz döneminde insanların gelir araması, Airbnb''nin evini kiraya verme modelinin doğru zamanda karşılık bulmasını sağladı.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '8dd72044-0849-4ac9-9d05-0760ae303207'::uuid, 'Şirketi kapatıp bir süre iş hayatından uzaklaşmak.', 'İşler kötü gidince stratejiyi, ürünü veya iş modelini kökten değiştirmek.', 'Yatırımcılara şirketin durumu hakkında gerçeğe aykırı ve eksik bilgi vermek.', 'Daha büyük bir ofise taşınıp çalışma ortamını genişletmek.', 'B', 'Pivot, beklenen sonuç alınmadığında girişimin stratejisini veya iş modelini köklü biçimde değiştirmesidir.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, '9f1a6362-1641-4190-86a4-2a145fe5e221'::uuid, 'Girişimciliğin kolay, eğlenceli ve düşük stresli bir uğraş olduğunu sanmak.', 'Girişimciliğin belirsizlik, stres ve yüksek risk taşıyan psikolojik zorluklarını.', 'Başarılı olmak için yalnızca fiziksel güce ihtiyaç duyulduğunu düşünmek.', 'Girişimcilik ile dağcılık sporunun aynı becerileri gerektirdiğini her zaman ileri sürmek.', 'B', 'Benzetme, girişimciliğin yüksek belirsizlik ve risk yanında ciddi psikolojik yük taşıdığını vurgular.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, 'db6e4681-b24c-4628-854c-1426cab31fd7'::uuid, 'Banka girişimciye hibe verir ve geri ödeme istemeden destek sağlar.', 'Banka ile melek yatırımcı arasında hiçbir temel fark bulunmadığını söyler.', 'Banka faiz ve teminat ister; yatırımcı potansiyele inanıp hisse alır.', 'Melek yatırımcı bankadan daha yüksek faiz talep ederek kredi verir.', 'C', 'Banka kredi karşılığında faiz ve teminat ister; melek yatırımcı ise ortaklık alarak riski girişimciyle paylaşır.'),
('11223344-5566-7788-9900-aabbccddeeff'::uuid, 'eca1991d-115f-4da2-9c9a-e556ae552f9e'::uuid, 'KOBİ''lerin her zaman daha fazla vergi ödemesi ve daha pahalı çalışması.', 'Start-up''ların mutlaka fiziksel bir ofisinin bulunmaması ve uzaktan çalışması.', 'KOBİ''lerin start-up''lardan daha zengin ve daha eski şirketler olması.', 'Start-up''ın hızlı büyüme ve pazarı değiştirme potansiyeline sahip olması.', 'D', 'Start-up''ı klasik KOBİ''den ayıran temel özellik, ölçeklenebilir ve yıkıcı inovasyon üretebilen bir model kurmasıdır.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, '19421870-d588-4fc6-8351-cf5d020deca3'::uuid, 'Yalnızca radyasyon yayması ve bunun her koşulda artması.', 'Kesintisiz üretim yapması ve hava koşullarından etkilenmemesi.', 'Atık üretmesi ve bu atıkların uzun süre yönetim gerektirmesi.', 'Yenilenebilir kaynak olması ve yakıt ihtiyacının hiç bulunmaması.', 'B', 'Fizyon santralleri hava koşullarından bağımsız, sürekli baz yük elektriği üretebilir.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, '43c6d7bc-ac3e-4797-8908-9558fdbab173'::uuid, 'Bugünün ihtiyaçlarını gelecek kuşakların imkânlarını azaltmadan karşılamak.', 'Doğalgaz ve petrol rezervlerini koruyarak uzun süre kullanmaya devam etmek.', 'Her durumda en ucuz ve en hızlı enerji kaynağına ulaşmaya çalışmak.', 'Çevreyi korumak için enerji tüketimini bütünüyle durdurmayı önermek.', 'A', 'Birleşmiş Milletler tanımı, bugünün ihtiyacını gelecek kuşakların imkânlarını tüketmeden karşılamayı vurgular.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, '7f52cabf-7bfa-4267-a485-f4177611a3de'::uuid, 'Enerji üretiminde ortaya çıkan negatif veya eksik miktarı ifade eder.', 'Şebekede yaşanan elektrik kesintisini ve buna bağlı kaybı anlatır.', 'Tasarruf ve verimlilikle hiç tüketilmeyen enerjiyi ifade eder.', 'Tüketicinin ödediği yüksek elektrik bedelini ve zam farkını anlatır.', 'C', 'Negawatt, verimlilik veya tasarruf sayesinde kullanılmasına gerek kalmayan enerjiyi anlatır.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, 'a3d5ed5b-61b8-4e59-8507-523627581e5e'::uuid, 'Atomları birleştirerek enerji üretmesi ve daha temiz bir seçenek olması.', 'Yakıt olarak uranyum kullanması ve atomları parçalayarak enerji üretmesi.', 'Mevcut santrallere göre daha fazla radyoaktif atık ve risk üretmesi.', 'Enerji üretirken daha fazla sera gazı salması ve iklimi etkilemesi.', 'A', 'Füzyon atom çekirdeklerini birleştirir; fisyondan farklı olarak daha az atık ve düşük emisyon hedefi taşır.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, 'a6a0075e-76a1-4660-a09e-c4e5df18e101'::uuid, 'Şehirlerde nüfusun ve yapı yoğunluğunun zaman içinde hızla artması.', 'Karayollarında trafik kazalarının daha sık yaşanması ve ulaşımı aksatması.', 'Enerji fiyatlarının yükselerek tüketicilerin bütçesini sürekli zorlaması.', 'Sera gazlarının küresel ısınmayı ve iklim değişikliğini hızlandırması.', 'D', 'Fosil yakıtların sera gazı salımı, metinde küresel ısınma ve iklim değişikliğinin temel nedeni olarak açıklanır.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, 'bafda58e-fb1a-4a6b-8acb-2058c8061f97'::uuid, 'Güneş ve rüzgâr santrallerinin her zaman tehlikeli çalışması.', 'Yenilenebilir santrallerin bütün koşullarda çok pahalı olması.', 'Üretimin sürekli olmaması nedeniyle depolama ihtiyacının doğması.', 'Güneş ve rüzgâr santrallerinin çalışırken çevreyi sürekli kirletmesi.', 'C', 'Güneş ve rüzgâr hava koşullarına bağlı olduğu için üretimin sürekliliği ve depolanması önemli bir sorundur.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, 'f03cbac0-5617-490e-8a45-76c70f7c989d'::uuid, 'Paneller ısındığında ülkenin bütün enerji ihtiyacının ve şebeke yükünün artması.', 'Kaynak çeşitliliği olmayınca gece ve bulutlu havalarda arz güvenliğinin zayıflaması.', 'Tek kaynağın kullanılmasıyla insanların enerji seçimlerinden sıkılması ve talebin düşmesi.', 'Güneşin her bölgede ve her mevsimde aynı sürede batması nedeniyle üretimin aksaması.', 'B', 'Tek kaynağa bağımlılık, o kaynak üretim yapamadığında şebekenin dengesini ve arz güvenliğini zayıflatır.'),
('0b1c2d3e-4f5a-6666-7777-555566667777'::uuid, 'f73f0054-844f-4263-89b5-9fe1cd441e51'::uuid, 'Taşların bugün de enerji sektöründe yaygın biçimde kullanılmaya devam edeceğini.', 'Petrol rezervlerinin hiçbir zaman tükenmeyeceğini ve gelecekte de yeterli kalacağını.', 'Maden çıkarma faaliyetlerinin yakın gelecekte bütünüyle ve kalıcı biçimde sona ereceğini.', 'Fosil yakıt çağının, daha temiz ve üstün alternatifler bulunduğunda sona ereceğini.', 'D', 'Söz, enerji dönüşümünün kaynakların bitmesini beklemeden daha iyi teknolojilerle gerçekleşebileceğini anlatır.');
